var L = 'en';
var CP = 'landing';
var CUR_COURSE = 0;
var QZ = {step:0,score:0,sel:null,answered:false,done:false,passed:false};
var CH_DONE = false;
var OB_SEL = [null,null,null];

function t(k){ return T[L][k] !== undefined ? T[L][k] : (T.en[k] || k); }

function SL(l){
  L = l;
  document.querySelectorAll('.lb').forEach(function(b){ b.classList.toggle('on', b.dataset.l === l); });
  RA();
}

/* =========================================================
   NAVIGATION
========================================================= */
function P(name){
  var mc = document.getElementById('mcOverlay');
  if(mc) mc.parentNode.removeChild(mc);
  document.querySelectorAll('.page').forEach(function(p){ p.classList.remove('on'); });
  var pg = document.getElementById('p-'+name);
  if(pg){ pg.classList.add('on'); pg.scrollTop = 0; }
  CP = name;
  var noNav = ['landing','login','signup','onboarding','paywall'];
  var noBN  = ['landing','login','signup','onboarding','paywall','course-detail'];
  var hasSidebar = noBN.indexOf(name) < 0;
  document.getElementById('BN').style.display = hasSidebar ? 'flex' : 'none';
  document.getElementById('app').classList.toggle('has-sidebar', hasSidebar);
  document.getElementById('TB').style.display = (name === 'landing' || name === 'onboarding') ? 'none' : 'flex';
  if(noNav.indexOf(name) < 0) UTB(name);
  if(noBN.indexOf(name) < 0) UBN(name);
  if(name === 'lesson'){ QZ={step:0,score:0,sel:null,answered:false,done:false,passed:false}; CH_DONE=false; RLS(); }
  if(name === 'onboarding'){ OB_SEL=[null,null,null]; ROB(0); }
  if(name === 'paywall') RPW();
}

function openCurLesson(){ P('lesson'); }
function openCourseDetail(idx){ CUR_COURSE = idx; RCD(); P('course-detail'); }
function goLesson(idx){ CUR_COURSE = idx; P('lesson'); }

function langSw(){
  return '<div class="lang-sw">'
    + '<button class="lb '+(L==='en'?'on':'')+'" data-l="en" onclick="SL(\'en\')">&#x1F1EC;&#x1F1E7; EN<\/button>'
    + '<button class="lb '+(L==='de'?'on':'')+'" data-l="de" onclick="SL(\'de\')">&#x1F1E9;&#x1F1EA; DE<\/button>'
    + '<\/div>';
}

function logoHTML(){
  return '<div class="logo-row" onclick="P(\'landing\')" style="cursor:pointer">'
    + '<div class="lmark" style="display:flex;align-items:center;justify-content:center"><img src="data:image/png;base64," width="22" height="22" style="border-radius:5px;object-fit:cover">\/div>'
    + '<span class="lname fd" style="background:linear-gradient(135deg,#c4b5fd,#9b7ff4);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text">Lumera<\/span>'
    + '<\/div>';
}

function UTB(n){
  var L2 = document.getElementById('TBL');
  var R  = document.getElementById('TBR');
  var titles = {dashboard:t('n0'),courses:t('csh'),'course-detail':t('ct')[CUR_COURSE],lesson:t('les_title'),progress:t('pg'),admin:t('ah'),paywall:'Premium'};
  if(n === 'lesson'){
    L2.innerHTML = '<button class="back-btn" onclick="P(\'course-detail\')">&#x2190; '+ t('ct')[CUR_COURSE] +'<\/button>';
    L2.onclick = null;
    R.innerHTML = langSw();
  } else if(n === 'course-detail'){
    L2.innerHTML = '<button class="back-btn" onclick="P(\'courses\')">&#x2190; '+t('csh')+'<\/button>';
    L2.onclick = null;
    R.innerHTML = langSw();
  } else {
    L2.innerHTML = logoHTML() + '<span class="fd" style="font-size:13px;font-weight:600;color:var(--t2);margin-left:4px">'+titles[n]+'<\/span>';
    L2.onclick = function(){ P('landing'); };
    R.innerHTML = langSw();
  }
}

function UBN(n){
  document.querySelectorAll('.ntab').forEach(function(b){ b.classList.toggle('on', b.dataset.p === n); });
  ['n0','n1','n2','n3','n4'].forEach(function(k,i){
    var el = document.getElementById('nl'+i);
    if(el) el.textContent = t(k);
  });
}

function RA(){
  RL(); RLG(); RSG(); RD(); RC(); RCD(); RLS(); RPR(); RAD(); RPW();
  if(['landing','login','signup','onboarding','paywall'].indexOf(CP) < 0){ UTB(CP); }
  if(['landing','login','signup','onboarding','paywall','course-detail'].indexOf(CP) < 0){ UBN(CP); }
}

/* =========================================================
   HELPERS
========================================================= */
function h(tag, cls, content, style, attrs){
  var s = style ? ' style="'+style+'"' : '';
  var a = attrs || '';
  return '<'+tag+(cls?' class="'+cls+'"':'')+s+a+'>'+content+'<\/'+tag+'>';
}
function div(cls, content, style){ return h('div',cls,content,style); }
function span(cls, content, style){ return h('span',cls,content,style); }

