/* =========================================================
   LESSON
========================================================= */
function renderStepBar(curStep){
  var labels = t('step_labels');
  var html = '<div class="les-step-bar" id="lesStepBar">';
  for(var i=0; i<labels.length; i++){
    var cls = 'step-c' + (i < curStep ? ' done' : i === curStep ? ' cur' : '');
    var inner = i < curStep ? '&#x2713;' : '<span style="font-size:9px">'+(i+1)+'<\/span>';
    html += '<div class="step-dot">'
      +'<button class="'+cls+'" title="'+labels[i]+'" onclick="scrollLesStep('+i+')">' + inner + '<\/button>'
      + (i < labels.length-1 ? '<div class="step-line'+(i < curStep ? ' done' : '')+'"><\/div>' : '')
      +'<\/div>';
  }
  html += '<\/div>';
  html += '<div style="padding:4px 20px 8px;font-size:11px;font-weight:600;color:var(--blu)">'+labels[curStep]+' \u2014 '+(curStep+1)+'/'+labels.length+'<\/div>';
  return html;
}

function updateStepBar(curStep){
  var bar = document.getElementById('lesStepBar');
  if(!bar) return;
  var labels = t('step_labels');
  var html = '';
  for(var i=0; i<labels.length; i++){
    var cls = 'step-c' + (i < curStep ? ' done' : i === curStep ? ' cur' : '');
    var inner = i < curStep ? '&#x2713;' : '<span style="font-size:9px">'+(i+1)+'<\/span>';
    html += '<div class="step-dot">'
      +'<button class="'+cls+'" title="'+labels[i]+'" onclick="scrollLesStep('+i+')">' + inner + '<\/button>'
      + (i < labels.length-1 ? '<div class="step-line'+(i < curStep ? ' done' : '')+'"><\/div>' : '')
      +'<\/div>';
  }
  bar.innerHTML = html;
  var lbl = document.getElementById('lesStepLbl');
  if(lbl) lbl.textContent = labels[curStep] + ' \u2014 ' + (curStep+1) + '/' + labels.length;
}

function scrollLesStep(idx){
  var ids = ['lesS0','lesS1','lesS2','lesS3','lesS4','lesS5'];
  var el = document.getElementById(ids[idx]);
  if(el) el.scrollIntoView({behavior:'smooth',block:'start'});
  updateStepBar(idx);
}

