    +'<div class="card" style="overflow:hidden;margin-bottom:24px">'
    +'<div style="padding:20px;border-bottom:1px solid var(--line2)">'
    +'<div class="fd" style="font-weight:700;font-size:16px;margin-bottom:4px">'+t('les_qh')+'<\/div>'
    +'<div style="font-size:12px;color:var(--t3)">'+t('les_qs2')+'<\/div>'
    +'<\/div>'
